msg.payload = http_body;

// Devuelve el mensaje
return msg;

let sensor_id = msg.topic.split("/")[2];
let sensedAt = new Date();
let energy_data = msg.payload.ENERGY
let mongo_payload = [];

let excludedKeys = ["TotalStartTime", "Total", "Yesterday", "Today", "Period"];

for (let key in energy_data) {
    if (!excludedKeys.includes(key)) {
        mongo_payload.push({
            metadata: {sensorId: sensor_id, type: key.toLowerCase()},
            timestamp: sensedAt,
            [key]: energy_data[key]
        })
    }
}

msg.payload = [mongo_payload]
return msg;

let sensor_id = msg.topic.split("/")[3];
let sensedAt = new Date();
let mongo_payload = [];
if (sensor_id === "Accuenergy") {
    let datalist = msg.payload.device.readings;

    const paramTypeMap = {
        V1: "voltage", V2: "voltage", V3: "voltage",
        I1: "current", I2: "current", I3: "current",
        P1: "power", P2: "power", P3: "power",
        Q1: "reactivepower", Q2: "reactivepower", Q3: "reactivepower",
        S1: "apparentpower", S2: "apparentpower", S3: "apparentpower",
        PF1: "pf", PF2: "pf", PF3: "pf"
    };

    for (let i of datalist) {
        let param = i["param"];
        let value = parseFloat(i["value"]);
        if (paramTypeMap.hasOwnProperty(param)) {
            let point_type = paramTypeMap[param];
            mongo_payload.push({
                metadata: { sensorId: sensor_id, type: point_type },
                timestamp: sensedAt,
                [param]: value.toFixed(2)
            });
        }
    }

    msg.payload = [mongo_payload];
    return msg;
} else {
    let datalist = msg.payload.data;
    for (let index = 0; index < datalist.length; index++) {
        let point_type = Object.keys(datalist[index])[0];
        let point = Object.values(datalist[index])[0];
        if (typeof point === "number" && !Number.isInteger(point)) {
            point = parseFloat(point.toFixed(2));
        }
        mongo_payload.push({
            metadata: { sensorId: sensor_id, type: point_type },
            timestamp: sensedAt,
            [point_type]: point
        });
    }

    msg.payload = [mongo_payload]
    return msg;
}

let mqtt_topic_fields = msg.topic.split("/");
let phase;
switch (mqtt_topic_fields[3]){
    case "0":
        phase = "A"
        break;
    case "1":
        phase = "B"
        break;
    case "2":
        phase = "C"
        break;
    default:
        phase = "Unknown"
        break;
}
let component = mqtt_topic_fields[4]
let sensor_id = mqtt_topic_fields[1];
let sensor_type = component + "_" + phase;
let sensedAt = new Date();
if(component !== "total_returned" && component !== "total"){
    msg.payload = [{
        metadata: { sensorId: sensor_id, type: component },
        [sensor_type]: msg.payload,
        timestamp: sensedAt
    }]
    return msg;
}else{
    return null;
}

let sensedAt = new Date();

let mongo_msg = {
    metadata: {
        sensorId: "shellyem3-349454756742"
    },
    timestamp: sensedAt
};

for (let key in msg.payload) {
    if (key.endsWith("total_returned")) {
        continue;
    }

    let datalist = key.split("/");

    let phaseNumber = datalist[3];
    let measurement = datalist[4];

    let phase;
    switch (phaseNumber) {
        case "0":
            phase = "A";
            break;
        case "1":
            phase = "B";
            break;
        case "2":
            phase = "C";
            break;
        default:
            phase = "unknown";
    }

    let new_key = measurement + phase;
    mongo_msg[new_key] = msg.payload[key];
}

return { payload: [mongo_msg] };

